import React, { useEffect, useRef, useState } from 'react';
import type { KHostBridgeApi, KHostBridgeFailureStatus, KHostBridgeHandoff, KHostBridgeSearch, KHostBridgeSong, KHostBridgeUiStatus, KHostPendingHandoff } from '../domain/khost-bridge';
import { Tooltip } from './Tooltip';

const messages: Record<KHostBridgeFailureStatus, string> = {
  'not-configured': 'Choose the private connection file generated by the enabled TPV bridge plugin in KHost.',
  'policy-blocked': 'Companion songs are hidden by this show’s age restriction or approved-version list because these external recordings have not been approved for it.',
  'configuration-error': 'The selected private connection file is unavailable, changed or not owner-only. Select the current connection file generated by KHost.',
  'unavailable': 'The KHost connection could not be confirmed. Check that KHost and the TPV bridge plugin are running.',
  'unauthorized': 'KHost rejected this bridge connection. Choose its freshly generated private connection file.',
  'invalid-request': 'Enter an artist or song title using 2–200 characters, then search again.',
  'busy': 'An external request is still being processed. Check its status before sending another.',
  'expired-result': 'This result or the host rules changed. Search again before sending it to KHost.',
  'handoff-unavailable': 'The installed provider did not offer an Enqueue action for this result.',
  'provider-unavailable': 'The KaraFun provider is unavailable in KHost. Enable its KaraFun plugin there.',
  'protocol-error': 'The companion response was incompatible. Update the TPV bridge plugin and check KHost.',
  'idempotency-conflict': 'That request identifier already belongs to another song. Check the KHost queue.',
  'unknown-request': 'The companion no longer has this request’s status. Check its queue before trying another handoff.',
  'sign-in-required': 'Open KHost and sign in through its KaraFun plugin, then search here again.',
};
const unresolved = (job: KHostPendingHandoff | null) => !!job && (job.sending || job.uncertain || job.result.status === 'handed-off' && job.result.state === 'pending');
const outcome = (value: KHostBridgeHandoff) => value.status === 'handed-off'
  ? value.state === 'complete' ? 'The provider’s Enqueue action completed in KHost. Check its queue and downloads, then operate playback there.'
    : value.state === 'failed' ? 'The external action failed. Check KHost’s queue and messages before trying another handoff.'
      : 'KHost accepted this handoff. It may still be downloading or waiting for input there.'
  : messages[value.status];

export function KHostBridgePanel({ bridge, scope, enabled = true }: { bridge: KHostBridgeApi; scope: string; enabled?: boolean }) {
  const [statusState, setStatus] = useState<KHostBridgeUiStatus | null>(null);
  const [statusScope, setStatusScope] = useState('');
  const [query, setQuery] = useState('');
  const [searchState, setSearch] = useState<KHostBridgeSearch | null>(null);
  const [searchScope, setSearchScope] = useState('');
  const [working, setWorking] = useState<'profile' | 'search' | 'handoff' | 'status' | null>(null);
  const [failure, setFailure] = useState('');
  const [job, setJob] = useState<KHostPendingHandoff | null>(null);
  const epoch = useRef(0), searchSequence = useRef(0);
  const currentScope = useRef(scope); currentScope.current = scope;
  const status = statusScope === scope ? statusState : null;
  const search = searchScope === scope ? searchState : null;
  const valid = (generation: number) => generation === epoch.current && currentScope.current === scope;
  const installStatus = (value: KHostBridgeUiStatus) => { setStatus(value); setStatusScope(scope); if (value.pending) setJob(value.pending); };

  useEffect(() => {
    const generation = ++epoch.current;
    ++searchSequence.current; setSearch(null); setStatus(null); setJob(null); setWorking(null); setFailure('');
    void bridge.cancelSearch().catch(() => {});
    void bridge.status().then(value => { if (valid(generation)) installStatus(value); })
      .catch(() => { if (valid(generation)) setFailure('Companion status could not be read. Try Refresh Connection.'); });
    return () => { ++epoch.current; ++searchSequence.current; void bridge.cancelSearch().catch(() => {}); };
  }, [bridge, scope]);

  useEffect(() => {
    if (!enabled) {
      // Hide stale discoveries without dropping the handoff outcome: a request
      // already sent to KHost may still need the host's attention.
      ++searchSequence.current;
      setSearch(null);
      void bridge.cancelSearch().catch(() => {});
    }
  }, [bridge, enabled]);

  const observe = async (active: KHostPendingHandoff, generation: number) => {
    let result: KHostBridgeHandoff;
    try { result = await bridge.handoffStatus(active.requestId); }
    catch { result = { status: 'unavailable', requestId: active.requestId, mayHaveBeenAccepted: true }; }
    if (!valid(generation)) return;
    setJob({ ...active, result, sending: false, uncertain: result.status !== 'handed-off' });
  };
  const automatic = !!status?.configured && !job?.sending && (job?.result.status === 'handed-off' && job.result.state === 'pending'
    || job?.result.status === 'unavailable' && job.uncertain);
  useEffect(() => {
    if (!automatic || !job) return;
    const generation = epoch.current, active = job; let alive = true, count = 0;
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      if (!alive || !valid(generation)) return;
      await observe(active, generation);
      if (alive && valid(generation) && ++count < 6) timer = setTimeout(() => void poll(), 1500);
    };
    timer = setTimeout(() => void poll(), 1500);
    return () => { alive = false; clearTimeout(timer); };
  }, [bridge, scope, automatic, job?.requestId, job?.result.status, job?.result.status === 'handed-off' ? job.result.state : '']);

  const profile = async (clear = false) => {
    if (working) return;
    const generation = epoch.current; ++searchSequence.current; setWorking('profile'); setFailure(''); setSearch(null);
    await bridge.cancelSearch().catch(() => {});
    try {
      const value = await (clear ? bridge.clearProfile() : bridge.chooseProfile());
      if (valid(generation)) installStatus(value);
    } catch { if (valid(generation)) setFailure('Choose the owner-only JSON connection file published by the TPV KHost bridge plugin. Its file is retained when the selection is removed.'); }
    finally { if (valid(generation)) setWorking(null); }
  };
  const refresh = async () => {
    if (working) return; const generation = epoch.current; setWorking('status'); setFailure('');
    try { const value = await bridge.status(); if (valid(generation)) installStatus(value); }
    catch { if (valid(generation)) setFailure('Companion status could not be read. Check that KHost is running.'); }
    finally { if (valid(generation)) setWorking(null); }
  };
  const runSearch = async () => {
    if (!enabled || working || unresolved(job)) return;
    const generation = epoch.current, sequence = ++searchSequence.current;
    setWorking('search'); setSearch(null); setSearchScope(scope); setFailure('');
    try {
      const result = await bridge.search(query);
      if (valid(generation) && sequence === searchSequence.current) setSearch(result);
    } catch { if (valid(generation) && sequence === searchSequence.current) setFailure('KHost search is unavailable. Your TPV queue and playback remain available.'); }
    finally { if (valid(generation)) setWorking(null); }
  };
  const send = async (song: KHostBridgeSong) => {
    if (!enabled || working || unresolved(job)) return;
    const generation = epoch.current, requestId = crypto.randomUUID();
    const active: KHostPendingHandoff = { requestId, title: song.title, artist: song.artist, uncertain: true, sending: true,
      result: { status: 'unavailable', requestId, mayHaveBeenAccepted: true } };
    setWorking('handoff'); setJob(active); setFailure('');
    try {
      const result = await bridge.handoff({ resultId: song.resultId, requestId });
      if (!valid(generation)) return;
      if (result.status === 'busy' && result.requestId !== requestId) {
        const value = await bridge.status(); if (valid(generation)) installStatus(value);
      }
      else setJob({ ...active, result, sending: false, uncertain: 'mayHaveBeenAccepted' in result && result.mayHaveBeenAccepted === true });
    } catch { if (valid(generation)) setJob({ ...active, sending: false }); }
    finally { if (valid(generation)) setWorking(null); }
  };
  const acknowledge = async () => {
    if (!job || !job.uncertain || job.sending || working) return;
    const generation = epoch.current; setWorking('status'); setFailure('');
    try {
      const value = await bridge.acknowledgeHandoff(job.requestId);
      if (valid(generation)) {
        ++epoch.current; ++searchSequence.current; setSearch(null); void bridge.cancelSearch().catch(() => {});
        setStatus(value); setStatusScope(scope); setJob(value.pending);
      }
    } catch { if (valid(generation)) setFailure('The handoff is still being sent. Wait for it to return, then check the KHost queue.'); }
    finally { if (currentScope.current === scope) setWorking(null); }
  };
  const ready = status?.connection.status === 'ready' && status.connection.providerAvailable;
  return <section className="provider-catalog-panel" aria-label="KaraFun via KHost companion">
    <h2>KaraFun via KHost <span className="badge">External Playback</span></h2>
    <p>Search the KaraFun plugin you already use in KHost. <strong>Send to KHost</strong> uses the singer selected there and its external queue. Start and control the song in KHost.</p>
    <ol>
      <li>Install the current KHost and its KaraFun plugin, then sign in to KaraFun there.</li>
      <li>Extract <code>TPV-KHost-Bridge-0.1.0.zip</code> from this release into KHost’s plugins folder. Enable <strong>The Proper Volume Companion Bridge</strong> and restart KHost.</li>
      <li>Choose the private <code>connection.json</code> shown in that plugin’s startup note. On Windows it is normally under <code>%LOCALAPPDATA%\TheProperVolume\KHostBridge</code>.</li>
    </ol>
    <div className="button-row">
      <button type="button" disabled={working !== null} onClick={() => void profile()}>Choose Private Bridge Profile…</button>
      {status?.configured && <button type="button" disabled={working !== null} onClick={() => void profile(true)}>Remove Profile Selection</button>}
      <button type="button" disabled={working !== null} onClick={() => void refresh()}>Refresh Connection</button>
    </div>
    {!status && !failure && <p role="status">Reading companion status…</p>}
    {status && <p role="status">{status.connection.status === 'ready'
      ? status.connection.providerAvailable ? 'Connected to KHost · KaraFun provider available · Playback stays in KHost.' : messages['provider-unavailable']
      : messages[status.connection.status]}</p>}
    <p className="muted">These companion results use a separate external queue. TPV’s own song library, queue and singer display use their existing playback sources.</p>
    {!enabled && <p role="status">KHost search is off. Enable KaraFun under Show in Search to use it.</p>}
    {enabled && <form className="library-toolbar" onSubmit={event => { event.preventDefault(); void runSearch(); }}>
      <label>Search KaraFun Through KHost<input type="search" value={query} maxLength={200} onChange={event => {
        setQuery(event.target.value); setSearch(null); ++searchSequence.current; void bridge.cancelSearch().catch(() => {});
      }} /></label>
      <button type="submit" disabled={!ready || working !== null || unresolved(job) || query.trim().length < 2}>Search KHost</button>
    </form>}
    {working === 'search' && <p role="status">Searching KaraFun through KHost…</p>}
    {enabled && search && (search.status !== 'ready' ? <p role="status">{messages[search.status]}</p> : <>
      <p className="muted">{search.songs.length} unblocked matches · External KHost queue</p>
      <div role="list" aria-label="KHost KaraFun songs">{search.songs.map(song => <div key={song.resultId} className="track-row provider-catalog-song" role="listitem">
        <div><strong>{song.title}</strong><small>{song.artist || 'Unknown artist'} · KaraFun via KHost</small></div>
        <Tooltip text="Send this song to the singer selected in KHost’s external queue. Playback remains in KHost.">
          <button type="button" disabled={!song.canHandoff || working !== null || unresolved(job)} onClick={() => void send(song)}>Send to KHost (External Queue)</button>
        </Tooltip>
      </div>)}</div>
    </>)}
    {job && <section aria-label="KHost handoff status" className="provider-catalog-card">
      <strong>{job.title}</strong><p role="status">{job.sending ? 'Sending to KHost…' : outcome(job.result)}</p>
      {unresolved(job) && <>
        <p className="muted">This request is locked while its outcome is uncertain or pending. Check KHost’s queue and downloads before sending another song.</p>
        <button type="button" disabled={working !== null || job.sending || !status?.configured} onClick={() => void observe(job, epoch.current)}>Check Handoff Status</button>
        {job.uncertain && <button type="button" disabled={working !== null || job.sending} onClick={() => void acknowledge()}>I Checked the KHost Queue — Clear Warning</button>}
      </>}
    </section>}
    {failure && <p role="alert">{failure}</p>}
  </section>;
}
